package io.redspace.ironsspellbooks.effect;

import net.minecraft.sounds.SoundEvents;
import net.minecraft.world.effect.MobEffect;
import net.minecraft.world.effect.MobEffectCategory;
import net.minecraft.world.entity.LivingEntity;

public class AirborneEffect extends MobEffect {
    public AirborneEffect(MobEffectCategory pCategory, int pColor) {
        super(pCategory, pColor);
    }

    @Override
    public boolean shouldApplyEffectTickThisTick(int pDuration, int pAmplifier) {
        return true;
    }

    public static final float damage_per_amp = 0.5f;

    @Override
    public boolean applyEffectTick(LivingEntity livingEntity, int pAmplifier) {
        if (!livingEntity.level.isClientSide) {
            if (livingEntity.horizontalCollision) {
                double d11 = livingEntity.getDeltaMovement().horizontalDistance();
                float f1 = (float) (d11 * 10.0D - 1.0D);
                //IronsSpellbooks.LOGGER.debug("AirborneEffect horizontalCollision: {}, {}", livingEntity.getDeltaMovement().horizontalDistance(),f1);
                if (f1 > 0.0F) {
                    livingEntity.playSound(SoundEvents.HOSTILE_BIG_FALL, 2.0F, 1.5F);
                    livingEntity.hurt(livingEntity.damageSources().flyIntoWall(), getDamageFromLevel(pAmplifier + 1));
                    return false;
                }
            }
        }
        return true;
    }

    public static float getDamageFromLevel(int level) {
        return 4 + level * damage_per_amp;
    }
}

public static boolean isFriendlyFireBetween(@Nullable Entity attacker, @Nullable Entity target) {
    if (attacker == null || target == null) {
        return false;
    }
    if (attacker instanceof IMagicSummon summon) {
        var tmp = summon.getSummoner();
        if (tmp != null) {
            attacker = tmp;
        }
    }
    if (target instanceof IMagicSummon summon) {
        var tmp = summon.getSummoner();
        if (tmp != null) {
            target = tmp;
        }
    }
    if (attacker.isPassengerOfSameVehicle(target)) {
        return true;
    }
    if (attacker instanceof Player playerAttacker && target instanceof Player playertarget
            && !playerAttacker.canHarmPlayer(playertarget)) {
        return true;
    }
    var team = attacker.getTeam();
    if (team != null) {
        return team.isAlliedTo(target.getTeam()) && !team.isAllowFriendlyFire();
    }
    //We already manually checked for teams, so this will only return true for any overrides (such as summons)
    return attacker.isAlliedTo(target);
}

